class Calc {
    static int value = 10;
    static int run() {
        try {
            value += 1;
            return value;
        } finally {
            value += 10;
            System.out.print("F" + value + ":");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        int r = Calc.run();
        System.out.print(r + ":" + Calc.value);
    }
}

class R implements AutoCloseable {
    private final String id;
    R(String id) { this.id = id; System.out.print("+" + id); }
    public void close() { System.out.print("-" + id); }
}
public class Main {
    public static void main(String[] args) {
        try (R first = new R("A");
             R second = new R("K")) {
            System.out.print("T");
        }
        System.out.print("E");
    }
}
